<script setup lang="ts">
import {onMounted,reactive,ref} from "vue";
import {useI18n} from "vue-i18n";
import {ElMessageBox,type FormInstance} from "element-plus";
import {ManagedDialog,ManagementTable,FloatingError,setErrorFeedback} from "@appnexus/ui";
import StatusHistoryButton from "../StatusHistoryButton.vue";
import type {ProductCatalogApi,UnitConversion,CatalogRow} from "./catalog";
/** 单位换算复用统一弹窗/列表，精确值不转为JavaScript浮点数。 */
const props=defineProps<{api:ProductCatalogApi;errorText:(e:unknown)=>string}>();
const emit=defineEmits<{close:[]}>();const {t}=useI18n();
const open=ref(true),rows=ref<UnitConversion[]>([]),units=ref<CatalogRow[]>([]),busy=ref(false),error=ref(""),editor=ref(false),form=ref<FormInstance>();
const draft=reactive({sourceUnitId:"",targetUnitId:"",factor:""}),calculation=reactive({id:"",quantity:"1",exact:"",display:""});
/** 候选分页读完，不能仅显示前100个单位。 */
async function load(){busy.value=true;try{rows.value=await props.api.conversions();const found:CatalogRow[]=[];let page=1,total=1;while(found.length<total){const result=await props.api.list("unit",{keyword:"",page:page++,size:100});total=result.total;if(!result.rows.length)break;found.push(...result.rows);}units.value=found;}catch(e){await setErrorFeedback(error,props.errorText(e));}finally{busy.value=false;}}
/** 创建失败保留输入，不自动重复写入。 */
async function save(){if(busy.value||!await form.value?.validate().catch(()=>false))return;busy.value=true;try{await props.api.createConversion({...draft});editor.value=false;await load();}catch(e){await setErrorFeedback(error,props.errorText(e));}finally{busy.value=false;}}
async function toggle(row:UnitConversion){try{await ElMessageBox.confirm(t("productConversion.statusHint"),t("productConversion.title"),{confirmButtonText:t(row.enabled?"masterData.disable":"masterData.enable"),cancelButtonText:t("masterData.cancel")});}catch{return;}busy.value=true;try{await props.api.conversionStatus(row.id,{enabled:!row.enabled,version:row.version});await load();}catch(e){await setErrorFeedback(error,props.errorText(e));}finally{busy.value=false;}}
async function calculate(){if(!calculation.id)return;busy.value=true;try{const result=await props.api.calculateConversion(calculation.id,calculation.quantity);calculation.exact=result.exact;calculation.display=result.display;}catch(e){calculation.exact="";calculation.display="";await setErrorFeedback(error,props.errorText(e));}finally{busy.value=false;}}
onMounted(load);
</script>
<template><ManagedDialog v-model="open" :title="t('productConversion.title')" :busy="busy" @closed="emit('close')"><FloatingError :title="error"/><p>{{t('productConversion.hint')}}</p>
<ManagementTable :title="t('productConversion.title')" :rows="rows" :loading="busy" :columns="[{key:'status',label:t('masterData.status'),width:100},{key:'sourceCode',prop:'sourceCode',label:t('productConversion.source'),minWidth:120},{key:'targetCode',prop:'targetCode',label:t('productConversion.target'),minWidth:120},{key:'factor',prop:'factor',label:t('productConversion.factor'),minWidth:180},{key:'operations',label:t('masterData.actions'),width:180}]" @refresh="load"><template #actions><el-button v-operation="'ProductUnit.createConversion'" type="primary" :disabled="busy" @click="editor=true">{{t('masterData.create')}}</el-button></template><template #status="{row}"><el-tag class="app-status-tag" :type="row.enabled?'success':'info'">{{t(row.enabled?'masterData.enabled':'masterData.disabled')}}</el-tag></template><template #operations="{row}"><StatusHistoryButton operation="ProductUnit.readConversionStatusHistory" :load="(page,size)=>api.statusHistory('conversion',row.id,page,size)" :error-text="errorText" /><el-button v-operation="'ProductUnit.setConversionStatus'" link :disabled="busy" @click="toggle(row)">{{t(row.enabled?'masterData.disable':'masterData.enable')}}</el-button></template></ManagementTable>
<el-form class="business-border-label-form" label-position="top" @submit.prevent="calculate"><el-form-item :label="t('productConversion.title')"><el-select v-model="calculation.id"><el-option v-for="r in rows.filter(r=>r.enabled)" :key="r.id" :value="r.id" :label="r.sourceCode+' → '+r.targetCode"/></el-select></el-form-item><el-form-item :label="t('productConversion.quantity')"><el-input v-model="calculation.quantity" maxlength="32"/></el-form-item><el-button v-operation="'ProductUnit.calculateConversion'" :loading="busy" :disabled="!calculation.id" @click="calculate">{{t('productConversion.calculate')}}</el-button><el-descriptions v-if="calculation.exact" :column="1" border><el-descriptions-item :label="t('productConversion.exact')">{{calculation.exact}}</el-descriptions-item><el-descriptions-item :label="t('productConversion.display')">{{calculation.display}}</el-descriptions-item></el-descriptions></el-form>
<ManagedDialog v-model="editor" :title="t('productConversion.title')" :busy="busy"><el-form ref="form" :model="draft" class="business-border-label-form" label-position="top" @submit.prevent="save"><el-form-item v-for="key in (['sourceUnitId','targetUnitId'] as const)" :key="key" :label="t(key==='sourceUnitId'?'productConversion.source':'productConversion.target')" :prop="key" :rules="[{required:true,message:t('masterData.required')}]"><el-select v-model="draft[key]" filterable @change="key==='sourceUnitId' && (draft.targetUnitId='')"><el-option v-for="u in units.filter(u=>u.enabled&&(key==='sourceUnitId'||(u.id!==draft.sourceUnitId&&u.dimensionCode===units.find(source=>source.id===draft.sourceUnitId)?.dimensionCode)))" :key="u.id" :value="u.id" :label="u.name+' / '+u.code"/></el-select></el-form-item><el-form-item :label="t('productConversion.factor')" prop="factor" :rules="[{required:true,message:t('masterData.required')},{pattern:/^(0|[1-9][0-9]{0,17})([.][0-9]{1,12})?$/,message:t('productConversion.invalid')}]"><el-input v-model="draft.factor" maxlength="31"/></el-form-item></el-form><template #footer><el-button v-operation="'ProductUnit.createConversion'" type="primary" :loading="busy" @click="save">{{t('masterData.save')}}</el-button></template></ManagedDialog></ManagedDialog></template>
